READ_ONLY = {"search_docs", "get_order"}
NEEDS_APPROVAL = {"send_email", "issue_refund"}

def as_untrusted(text: str, source: str) -> str:
    # Delimiting helps the model a little; it guarantees nothing
    return f"<untrusted source={source!r}>\n{text}\n</untrusted>"

def authorize(call, session) -> str:
    if call.name in READ_ONLY:
        return "allow"
    if call.name not in NEEDS_APPROVAL:
        return "deny"  # default-deny anything unknown
    # Check arguments against data the model cannot change
    if call.name == "issue_refund" and not owns_order(session.user_id, call.args["order_id"]):
        return "deny"
    return "ask_human"

def run_step(session, messages):
    call = llm_propose(messages)  # model output is an untrusted proposal
    decision = authorize(call, session)
    if decision == "allow":
        return execute(call, as_user=session.user_id)  # user's scopes, not a service account
    if decision == "ask_human":
        return request_confirmation(session.user_id, call)  # show the exact args
    return log_blocked(session, call)
